 const string Folder="Assets/Recoil3D/BlockedExodus",Marker="Blocked civilian exodus - road barrier queue and crossing car";
 static Material concrete,iron,wood,red,white,rust;static int serial;
 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();}
 static Transform G(Transform p,string n,Vector3 at){var t=new GameObject(n).transform;t.SetParent(p,false);t.position=at;return t;}
 static Transform B(Transform p,string n,Vector3 at,Vector3 size,Material m){var t=GameObject.CreatePrimitive(PrimitiveType.Cube).transform;t.name=n;t.SetParent(p,false);t.position=at;t.localScale=size;Object.DestroyImmediate(t.GetComponent<Collider>());t.GetComponent<Renderer>().sharedMaterial=m;return t;}
 static Material Mat(string n,Color colour){var path=Folder+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Recoil/3D/Weathered Surface"));AssetDatabase.CreateAsset(m,path);}m.color=colour;m.enableInstancing=true;m.SetFloat("_Glossiness",.06f);m.SetFloat("_Weathering",.85f);EditorUtility.SetDirty(m);return m;}
 static Bounds BoundsOf(Transform t){var rs=t.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static void Pose(Transform t,Vector3 at,float yaw,bool keepClear=true){t.position=at;t.rotation=Quaternion.Euler(0,yaw,0);var b=BoundsOf(t);at.y+=.02f-b.min.y;t.position=at;if(keepClear){b=BoundsOf(t);if(at.z>0&&b.min.z<1.5f)t.position+=Vector3.forward*(1.5f-b.min.z);if(at.z<0&&b.max.z> -1.5f)t.position+=Vector3.back*(b.max.z+1.5f);}}
 static Transform Clone(Transform source,Transform parent,string name,Vector3 at,float yaw){var copy=Object.Instantiate(source.gameObject,parent).transform;copy.name=name;copy.gameObject.SetActive(true);foreach(var c in copy.GetComponentsInChildren<Collider2D>())Object.DestroyImmediate(c);Pose(copy,at,yaw);return copy;}
 static void Solid(Transform parent,string name,Vector2 at,Vector2 size){var t=G(parent,name,new Vector3(at.x,at.y,0));var box=t.gameObject.AddComponent<BoxCollider2D>();box.size=size;t.gameObject.AddComponent<RecoilSurfaceVisibility>().blocksSight=false;}
 static void Batch(Transform root){var filters=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.GetComponent<MeshRenderer>()&&!f.name.StartsWith("Car - ")).ToArray();foreach(var group in filters.GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial)){var m=new Mesh{indexFormat=IndexFormat.UInt32};m.CombineMeshes(group.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);string path=Folder+"/Exodus fixtures only v5 visual batch "+(serial++)+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,path);var t=G(root,"Combined static exodus detail - "+group.Key.name,Vector3.zero);t.gameObject.AddComponent<MeshFilter>().sharedMesh=m;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=group.Key;foreach(var f in group){Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);}}}
 static void Barricade(Transform parent){var g=G(parent,"Temporary uneven road closure - no concrete bases",new Vector3(-66,0,0));
  int n=0;foreach(float z in new[]{-27f,-23.4f,-20.0f,-16.8f,-13.1f,-9.6f,-6.2f,-2.7f,2.8f,6.3f,9.5f,13.2f,16.6f,20.1f,23.6f}){
   float x=-66+Mathf.Sin(n*2.1f)*.40f,y=.93f+(n%3-1)*.08f;var module=G(g,"Portable timber trestle "+n,new Vector3(x,0,z));
   var beam=B(module,"Crooked temporary barrier board",new Vector3(x,y,z),new Vector3(.12f,.22f,2.65f),white);beam.rotation=Quaternion.Euler((n%3-1)*4,(n%2==0?1:-1)*8,0);
   for(int k=0;k<3;k++){var stripe=B(module,"Worn red paint on temporary board",new Vector3(x+.072f,y,z-.83f+k*.82f),new Vector3(.024f,.21f,.30f),red);stripe.rotation=beam.rotation;}
   foreach(float zz in new[]{z-.8f,z+.8f})foreach(float side in new[]{-1f,1f}){var leg=B(module,"Splayed trestle timber leg",new Vector3(x+side*.23f,.46f,zz),new Vector3(.095f,.99f,.10f),wood);leg.rotation=Quaternion.Euler(0,0,side*27);}
   if(n%4==1){var loose=B(module,"Loose fallen timber beside road closure",new Vector3(x+.40f,.055f,z+.2f),new Vector3(.12f,.10f,1.8f),wood);loose.rotation=Quaternion.Euler(0,29+n,0);}n++;
  }
  var sign=B(g,"Hand-hung closure sign",new Vector3(-65.65f,1.40f,2.5f),new Vector3(.95f,.65f,.06f),white);sign.rotation=Quaternion.Euler(0,-7,8);
 }
 static void ExtraRoofCar(Transform parent,Transform template,float x,int type,string name){var car=Clone(template,parent,name,new Vector3(x,0,0),90);Pose(car,new Vector3(x,0,0),90,false);float length=type==0?4.5f:3.65f,cabin=type==0?2.15f:2.2f,cf=-length*.5f+1.25f;Solid(parent,name+" lower body",new Vector2(x,.43f),new Vector2(length-.12f,.82f));Solid(parent,name+" bonnet",new Vector2(x+(-length*.5f+cf)*.5f,.72f),new Vector2(1.22f,.52f));Solid(parent,name+" roof",new Vector2(x+cf+cabin*.5f,1.185f),new Vector2(cabin-.32f,.81f));}
 static void Crate(Transform p){var at=new Vector3(-64.1f,.35f,0);B(p,"Weathered wooden crate - jump step",at,new Vector3(1.2f,.70f,2.6f),wood);for(int i=0;i<5;i++)B(p,"Crate top plank",new Vector3(-64.56f+i*.23f,.708f,0),new Vector3(.21f,.025f,2.62f),wood);foreach(float z in new[]{-1.32f,1.32f}){foreach(float x in new[]{-64.57f,-63.63f})B(p,"Crate corner batten",new Vector3(x,.35f,z),new Vector3(.11f,.72f,.06f),wood);B(p,"Crate diagonal brace",new Vector3(-64.1f,.35f,z),new Vector3(1.05f,.09f,.065f),wood).rotation=Quaternion.Euler(0,0,25);}
 }
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");var s=SceneManager.GetSceneByPath("Assets/Scenes/3D/RecoilPrototype.unity");if(!s.isLoaded)throw new Exception("Open outdoor scene first");var w=All<RecoilPrototype>(s).Single();if(w.transform.Find(Marker))return "Already applied";string backup="Backups/BlockedExodus/"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";Directory.CreateDirectory(Path.GetDirectoryName(backup));EditorSceneManager.SaveScene(s,backup,true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();serial=0;
  concrete=Mat("Old roadblock concrete",new Color(.31f,.32f,.28f));iron=Mat("Dark rusting barrier iron",new Color(.13f,.16f,.15f));wood=Mat("Old packing crate timber",new Color(.31f,.25f,.16f));red=Mat("Weathered red closure paint",new Color(.28f,.075f,.05f));white=Mat("Dirty ivory closure paint",new Color(.43f,.42f,.34f));rust=Mat("Rust beneath closure fixings",new Color(.20f,.105f,.05f));
  var routes=All<RecoilDoor>(s).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position).ToArray();var pumps=All<FuelPumpInteraction>(s).Select(p=>p.transform.position).ToArray();var spawn=w.transform.Find("Player Spawn").position;
  var existing=w.transform.Find("Opening approach expanded 20m - editable/Abandoned vehicles along the new approach").Cast<Transform>().ToArray();if(existing.Length!=12)throw new Exception("Unexpected approach vehicle count");var templates=existing.Take(4).ToArray();var root=G(w.transform,Marker,Vector3.zero);var art=G(root,"Queue and closure visual geometry",Vector3.zero);Barricade(art);
  float[] yaws={72,107,82,111,69,98,77,113,86,105,74,100};for(int row=0;row<4;row++){float front=-65.55f+(row%2)*.16f;for(int col=0;col<3;col++){int i=row*3+col;Pose(existing[i],new Vector3(-62,0,3.8f+row*3.7f+Mathf.Sin(i*2)*.25f),yaws[i]);var bounds=BoundsOf(existing[i]);existing[i].position+=Vector3.right*(front-bounds.min.x);front=BoundsOf(existing[i]).max.x+.08f+(col%2)*.14f;}}
  var cluster=G(art,"Queue spills onto road shoulders",Vector3.zero);for(int i=0;i<6;i++){float x=-62.6f+(i%3)*4.6f,z=i<3?18.2f:21.8f;Clone(templates[i%4],cluster,"Abandoned evacuation queue shoulder car "+i,new Vector3(x,0,z),90+(i%3-1)*14);}
  var foreground=G(art,"Foreground cars restored - dense at entry then taper",Vector3.zero);float[] fy={72,108,79,112,67,98};for(int row=0;row<2;row++){float front=-65.55f+row*.2f;for(int col=0;col<3;col++){int i=row*3+col;var foreCar=Clone(templates[i%3],foreground,"Foreground congested exit car "+i,new Vector3(-62,0,-4.0f-row*4-col*.12f),fy[i]);var bounds=BoundsOf(foreCar);foreCar.position+=Vector3.right*(front-bounds.min.x);front=BoundsOf(foreCar).max.x+.10f;}}
  var east=G(art,"Right forecourt - failed overtaking and merging",Vector3.zero);float[] ex={-31.0f,-25.8f,-20.2f,-29.5f,-24.3f,-19.4f,-29,-23};float[] ez={3.9f,3.8f,4.4f,7.8f,7.9f,8.2f,11.6f,11.8f};float[] ey={92,76,112,87,58,105,65,96};for(int i=0;i<ex.Length;i++)Clone(templates[(i+1)%4],east,"Overtaking vehicle blocked at forecourt right "+i,new Vector3(ex[i],0,ez[i]),ey[i]);
  // One solid estate car is the deliberately authored traversal obstacle.
  var crossing=G(root,"Crossing car and crate - model and collision together",Vector3.zero);var car=Clone(templates[1],crossing,"Estate car blocking operation plane - climb over roof",new Vector3(-60.5f,0,0),90);Pose(car,new Vector3(-60.5f,0,0),90,false);Crate(crossing);ExtraRoofCar(crossing,templates[0],-55.8f,0,"Second saloon - continue over bonnet and roof");ExtraRoofCar(crossing,templates[2],-51.4f,2,"Third hatchback - final roof before road");
  Solid(crossing,"Solid crate top Y0.72",new Vector2(-64.1f,.36f),new Vector2(1.2f,.72f));Solid(crossing,"Solid estate lower body",new Vector2(-60.5f,.43f),new Vector2(4.78f,.82f));Solid(crossing,"Solid estate bonnet top Y0.98",new Vector2(-62.31f,.72f),new Vector2(1.22f,.52f));Solid(crossing,"Solid estate cabin roof top Y1.59",new Vector2(-60.125f,1.185f),new Vector2(2.85f,.81f));
  var clutter=G(art,"Abandoned luggage at failed exit",Vector3.zero);for(int i=0;i<8;i++){float x=-65.0f+i%4*2.5f,z=i<4?2.5f:9.1f;var bag=B(clutter,"Dusty case left beside abandoned car",new Vector3(x,.17f,z),new Vector3(.58f,.34f,.40f),i%2==0?wood:iron);bag.rotation=Quaternion.Euler(0,i*31,0);B(clutter,"Case handle",bag.position+Vector3.up*.19f,new Vector3(.16f,.035f,.035f),iron);}
  foreach(var t in existing.Concat(cluster.Cast<Transform>()).Concat(east.Cast<Transform>()).Concat(foreground.Cast<Transform>())){var b=BoundsOf(t);if(b.min.z<1.3f&&b.max.z> -1.3f)throw new Exception("Unintended vehicle blocks lane "+t.name);}
  ForecourtEditableCarsPass.SplitBeforeStaticBatch(art);Batch(art);Physics2D.SyncTransforms();if(!routes.SequenceEqual(All<RecoilDoor>(s).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position)))throw new Exception("Door changed");if(!pumps.SequenceEqual(All<FuelPumpInteraction>(s).Select(p=>p.transform.position)))throw new Exception("Pump changed");if(spawn!=w.transform.Find("Player Spawn").position)throw new Exception("Spawn changed");
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);if(!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");Directory.CreateDirectory("output/blocked-exodus");string report="PASS roadblock X=-66, spawn X="+spawn.x+" (13m approach);12 existing vehicles form compressed exit queue,6 extra shoulder cars,8 overtaking cars at right; three solid cars across operation plane and .72m wooden crate with10 aligned hard colliders;6 restored foreground cars taper toward forecourt; other cars clear Z=-1.3..1.3. Pumps/doors/spawn retained. Backup: "+backup;File.WriteAllText("output/blocked-exodus/verification.txt",report);File.WriteAllText("output/blocked-exodus/references.txt","Visual research, not a real-world setting assignment:\nIPN street closure and civilian road checks,1981/82: https://archiwum.ipn.gov.pl/pl/aktualnosci/63268,Stan-wojenny-w-dokumentach-i-na-zdjeciach-z-zasobu-Archiwum-IPN.html\nEvacuation congestion / traffic shoulders: https://www.pbs.org/newshour/show/rita-evacuation-in-texas\nComposition adaptation: vehicles face toward blocked exit; compressed nose-to-tail spacing near barrier; diagonally stopped vehicles show unsuccessful overtaking. All aging, abandoned luggage and layouts are fictional1978 aftermath seen1982.\n");return report;
 }
